use vstd::prelude::*;

verus! {

    // append takes a vector v of u64s (length ≤ 100), and an element elem,
    // and returns a new vector res = v ++ [elem].
    fn append(v: &Vec<u64>, elem: u64) -> Vec<u64>
        requires
            v.len() <= 100,                           // input length at most 100
        ensures
            res.len() == v.len() + 1,                 // output length = input length + 1
        ensures
            // for all valid indices i in [0, v.len()), res[i] == v[i]
            forall(|i: int| 0 <= i && i < (v.len() as int) ==>
                res[i as usize] == v[i as usize]
            ),
        ensures
            // the last element of res is the appended elem
            res[v.len()] == elem
    {
        let mut res: Vec<u64> = Vec::new();
        let mut i: usize = 0;
        // Copy all elements of v into res
        while i < v.len()
            invariant
                i <= v.len(),
                res.len() == i,
                // for all j < i, res[j] == v[j]
                forall(|j: int| 0 <= j && j < (i as int) ==>
                    res[j as usize] == v[j as usize]
                ),
            decreases
                v.len() - i
        {
            res.push(v[i]);
            i += 1;
        }
        // Append the new element
        res.push(elem);
        res
    }

}

